class Base64Utils{static encode(t){return btoa(t).replace(/\+/g,"-").replace(/\//g,"_").replace(/=/g,"")}static decode(t){return t=(t+="=".repeat((4-t.length%4)%4)).replace(/-/g,"+").replace(/_/g,"/"),atob(t)}}class HttpClient{constructor(t,e,s=!0){this.baseUrl=t.replace(/\/$/,""),this.apiKey=e,this.useSSL=s,this.useSSL&&this.baseUrl.startsWith("http://")?this.baseUrl=this.baseUrl.replace("http://","https://"):!this.useSSL&&this.baseUrl.startsWith("https://")&&(this.baseUrl=this.baseUrl.replace("https://","http://"))}async request(t,e,s=null){const r=`${this.baseUrl}${e}`,a={method:t,headers:{"X-API-Key":this.apiKey,"Content-Type":"application/json"}};s&&(a.body=JSON.stringify(s));try{const t=await fetch(r,a),e=await t.json();if(!t.ok)throw new Error(`${t.status}: ${e.message||"Unknown error"}`);return e}catch(t){if("TypeError"===t.name&&t.message.includes("fetch"))throw new Error("Network error: Could not connect to server");throw t}}get(t){return this.request("GET",t)}post(t,e){return this.request("POST",t,e)}}class IWebAuthClient{constructor(t){if(!t.baseUrl||!t.apiKey)throw new Error("baseUrl and apiKey are required");this.httpClient=new HttpClient(t.baseUrl,t.apiKey,!1!==t.useSSL)}async login(t){const e=Base64Utils.encode(t);return await this.httpClient.post("/login",{email:e})}async validate(t,e){return await this.httpClient.post(`/validate/${t}`,{code:e})}async checkSession(t){return await this.httpClient.get(`/session/check/${t}`)}async touchSession(t){return await this.httpClient.post(`/session/touch/${t}`)}async createDelegatedSession(t,e){return await this.httpClient.post(`/session/delegate/${t}`,{target_api_key:e})}async logout(t){return await this.httpClient.post(`/session/logout/${t}`)}async getUserInfo(t){return await this.httpClient.get(`/user/${t}/info`)}async getUserToken(t){return await this.httpClient.get(`/user/${t}/token`)}async isSessionActive(t){try{const e=await this.checkSession(t);return e.data&&!0===e.data.active}catch{return!1}}}